package main

import (
	"bytes"
	"fmt"
	"io"
	"net/http"
	"os"
	"strings"
)

func main() {
	const base = "https://lapi.example.com"

	body := []byte(`{
  "model": "gpt-4o",
  "messages": [
    {
      "content": "你是一个耐心的编程助手",
      "role": "system"
    },
    {
      "content": "用一句话解释什么是 API 网关",
      "role": "user"
    }
  ],
  "stream": false,
  "temperature": 0.7
}`)
	req, err := http.NewRequest("POST", base + "/v1/chat/completions", bytes.NewReader(body))
	if err != nil {
		panic(err)
	}
	req.Header.Set("Authorization", "Bearer "+os.Getenv("LD_API_KEY"))
	req.Header.Set("Content-Type", "application/json")

	res, err := http.DefaultClient.Do(req)
	if err != nil {
		panic(err)
	}
	defer res.Body.Close()

	if res.StatusCode != http.StatusOK {
		msg, _ := io.ReadAll(res.Body)
		panic(fmt.Sprintf("%d %s", res.StatusCode, msg))
	}
	out, _ := io.ReadAll(res.Body)
	fmt.Println(strings.TrimSpace(string(out)))
}

